SELECT T1."ItemCode", P."BcdCode" AS "Barcode",T3."ItemName",T4."UomCode", IFNULL((Select (case when B."UomEntry"=X."UomEntry"  and X."UomEntry"=Y."BaseUom" then B."Price"when B."UomEntry"=X."UomEntry"  and X."UomEntry"<>Y."BaseUom" then B."Price"*1/X."AltQty"*X."BaseQty"when B."UomEntry"<>X."UomEntry" and X."UomEntry"<>Y."BaseUom" then B."Price"*1/X."AltQty"*X."BaseQty"when B."UomEntry"<>X."UomEntry" and X."UomEntry"=Y."BaseUom" then B."Price"else 0 end) from OITM C inner join (SELECT H."ItemCode",IFNULL((IFNULL(H."INMPrice", 0)/H."NumPerMsr"),0)-IFNULL((IFNULL(A1."INMPrice", 0)/A1."NumPerMsr"),0) as "Price", H."UomCode",H."UomEntry",H."NumPerMsr",Row_Number() over(partition by H."ItemCode" order by H."DocEntry" Desc) as "RN" FROM "PCH1" H left join OPCH A3 on A3."DocEntry"=H."DocEntry" left join ORPC A2 on  A2."U_BaseNum"=A3."DocNum" left  join RPC1 A1 on A2."DocEntry"=A1."DocEntry" and A1."ItemCode"=H."ItemCode" and A1."NoInvtryMv"='Y' where H."DocDate"<=T1."FromDate" and IFNULL(H."U_normalqty",0)<>0)B on C."ItemCode"=B."ItemCode" left join OUGP Y on Y."UgpEntry"=C."UgpEntry"  left JOIN UGP1 X ON Y."UgpEntry" = X."UgpEntry" where "RN"=1 and  B."ItemCode" =T2."ItemCode" and  X."UomEntry"=T2."UomEntry"),0) as "Item Cost", IFNULL(CASE WHEN T3."IUoMEntry" = T2."UomEntry" THEN  (SELECT "Price" FROM ITM1 WHERE "ItemCode" = T2."ItemCode" AND "PriceList" = '4') ELSE (SELECT "Price" FROM ITM9 WHERE "ItemCode" = T2."ItemCode" AND "PriceList" = '4' AND "UomEntry" = T2."UomEntry") END, 0) AS "Retail Price" ,T2."Price" "Offer Price",T1."FromDate", T1."ToDate", T1."U_PromName" "Promotion Name",T5."ItmsGrpNam" "Item Group", T1."LINENUM"  FROM "SPP1" T1 INNER JOIN "SPP2"  T2 On T1."ItemCode"=T2."ItemCode" and T1."CardCode"=T2."CardCode"  and T1."ListNum"=4 and T2."SPP1LNum"=T1."LINENUM" INNER JOIN OITM T3 ON T2."ItemCode" = T3."ItemCode" LEFT JOIN OBCD P on P."ItemCode"=T2."ItemCode" and T2."UomEntry"=P."UomEntry" INNER JOIN OUOM T4 ON T2."UomEntry" = T4."UomEntry" INNER JOIN OITB T5 ON T3."ItmsGrpCod" = T5."ItmsGrpCod"  WHERE T1."ToDate">=TO_CHAR(ADD_SECONDS(CURRENT_TIMESTAMP,-10800),'YYYYMMDD') and T1."ToDate"<=TO_CHAR(ADD_SECONDS(CURRENT_TIMESTAMP,75600),'YYYYMMDD')
